-- GENERATED by `wfj generate` from data/gossip/gossip-51.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["510bd326f8ff64c4"] = { "I nani non si ubriacano, <signorino/signorina>. È solo che barcollo un pochino.\n\nComunque, Windsor? Secondo me è da qualche parte nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. È la città dei ⟦Dark Iron=Ferroscuro⟧, per voi gente ignorantata.", "." },
  ["5125dfc9eaa7d7d9"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ si trova sul lato sud del ⟦Field of Strife=Pian della Discordia⟧, a est della Torre di Brinarossa.\n\nAl momento è sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["5128192218294558"] = { "Tresa Farmountain ha visto la sua parte di maltempo, ma grazie alla sua conoscenza della sopravvivenza ne è uscita sempre di buon umore.\n\nSe vuoi parlarle, la trovi nel Military Ward, a sud dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["512ff5764aa91700"] = { "Morto? Ti ha dato di volta il cervello, {name}? Pardon, <signor/signora> {name}! Windsor non sarebbe mai morto per una cinquantina di orchi. Com'è vero che il sanguinaccio di Thelsamar è il cibo più gustoso che il mondo conoscerà mai, eccolo lì, in piedi: era coperto di pezzi d'orco dalla testa ai piedi, inzuppato in circa diciotto strati del loro sangue, ma era decisamente vivo... e molto, molto arrabbiato.", "." },
  ["513e239330ee24f8"] = { "Sequenza di autodistruzione attivata.", "." },
  ["514585e49a114ecd"] = { "Nani!!! Ora mi stai dicendo che i nani in origine discendevano dai Terrigeni?!", "." },
  ["5147dfd0f490920c"] = { "A volte penso che ci sia un grosso nuvolone grigio in cielo che ci fa piovere addosso solo sfortuna. Prima ci hanno cacciati dalla nostra terra, e ora non riusciamo nemmeno ad andarcene dalle ⟦Westfall=Marche Occidentali⟧. È tutto un disastro. Bisogna fare qualcosa.", "." },
  ["514b489bfd068a7f"] = { "Interessante, molto interessante. L'hai trovato a Durotar, {name}?", "." },
  ["51546d57af0c4ca5"] = { "Qual è il problema, {name}? Dobbiamo attaccare prima che lo facciano i ⟦Bloodsail Buccaneers=Bucanieri Velerosse⟧!", "." },
  ["51558f6b800becfb"] = { "Allora, mettiamo che io trovi questa pelle: cos'altro ti servirebbe e cosa potresti fare davvero?", "." },
  ["5155db4ac9a06adf"] = { "Se ti interessa cucire il cuoio, sei proprio nel posto giusto. Faldron e Telonis sono veri artisti, e spero di imparare molto da loro.", "." },
  ["5162b0bf49dfc611"] = { "Se usiamo la sequenza giusta dovremmo cavarcela. Ci vorrà solo un bel po' di studio prima di cominciare.", "." },
  ["516abc04a994efc5"] = { "Mi dispiace davvero, {class}, ma il tuo spirito non ha mai conosciuto gli orrori che attendono fra le rovine in fiamme di Stratholme, quindi la nostra magia non può portarti in città.", "." },
  ["516e97bd98ad8d1f"] = { "La vita è piena di domande, {class}. Non riuscirai mai a rispondere a tutte, ma con un po' di tempo e di studio forse diventerai un po' più sapiente.", "." },
  ["517acf1646a46428"] = { "Non avvicinarlo oltre, mortale. Sento il male che scorre nel sigillo da dove mi trovo.\n\nDammi un momento per esaminare l'oggetto: tienilo saldo.", "." },
  ["517bb8508978af3e"] = { "La ⟦Cache of Mau'ari=Cassa di Mau'ari⟧ custodisce grandi segreti... Le schegge usate per crearla sono riflettenti, e puoi usare la sua superficie lucente per assorbire potere da altre cose e poi rifletterlo su di te.\n\nSe tieni il talismano nell'inventario raccogli e'ko, il potere spirituale delle bestie che combatti. Quando trovi e'ko, portalo a Mau'ari.", "." },
  ["517cba8286657f4d"] = { "Qualcosa si muove vicino a ⟦Southwind Village=Vento del Sud⟧! È... è una di quelle creature vermisabbio! Attenzione!", "." },
  ["517cd5f6f67c298e"] = { "Parla con ⟦Grezz Ragefist=Spazzy Pugnocrudele⟧ nella Hall of the Brave, nella ⟦Valley of Honor=Valle dell'Onore⟧. E metti una buona parola per me!", "." },
  ["517d485b26c10712"] = { "Battete le mani tutti quanti, e tutti quanti battete le mani!", "." },
  ["517e5eee791ffd14"] = { "%s si apre. Il contenuto aggredisce i tuoi sensi con un odore nauseabondo. Dentro vedi quelli che sembrano enormi escrementi di uccello e moltissimo sangue.", "." },
  ["5197f79654486d36"] = { "Beh, non vedevo lame così belle da quando ho lasciato Lordaeron con Proudmoore e la sua gente. Pare che non possa insegnarti molto di più, ma se trovassi ⟦Borgus Steelhand=Borgus Mandacciaio⟧ scommetto che lui potrebbe mostrarti qualcosa. Il miglior Fabbro d'Armi che abbia mai conosciuto.", "." },
  ["519fd7700cf36199"] = { "Il vento ti saluti, amico. Ho l'autorizzazione a offrire a chi è {race} come me un rapido passaggio fino alla città di ⟦Stormwind=Roccavento⟧. Usa pure questo portale quando preferisci.", "." },
  ["51a1dbef0b134bbb"] = { "Non smetti mai di sorprendermi: è incredibile a cosa possa sopravvivere una persona.", "." },
  ["51a32ae824f9c865"] = { "Libera la tua furia!", "." },
  ["51a4315366faa2e4"] = { "Affascinante, custode del sapere. Continua, ti prego.", "." },
  ["51a6902c9903c685"] = { "%s continua a cercare e mette altri teschi nella sua cassa.", "." },
  ["51ad66016a016a4e"] = { "Se pescassi bene quanto parli, nell'oceano non resterebbe più un pesce.", "." },
  ["51b85ea61a8a1136"] = { "Continua a portarne! Ci servono altre provviste per ricostruire...", "." },
  ["51ba03394b0bb708"] = { "Accesso in corso...\n\nVuoto -- ingegnere <#skill_level == n3wb>\n\n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\n\nACCESSO NEGATO!", "." },
  ["51beadcd15ade439"] = { "Borgosh! {name} è <pronto/pronta> per l'addestramento.", "." },
  ["51bee195fcde4ab4"] = { "Abbiamo sparso le Carte di Lunacupa in tutto il mondo per vedere se qualche persona meritevole riesce a completare una serie di uno dei quattro semi. Se riesci a raccogliere tutte e otto le carte di uno dei semi, ti ricompenseremo con una delle grandi Carte di Lunacupa, che funziona come un potente monile e anche come legame con la ⟦Darkmoon Faire=Fiera di Lunacupa⟧.", "." },
  ["51ce09eb810e6220"] = { "Troverai una cassetta della posta appena fuori dalla locanda, vicino alla strada che esce dal paese verso nord.", "." },
  ["51d05c749119fe65"] = { "Nell'era della guerra, ⟦Razelikh the Defiler=Razelikh il Profanatore⟧ era il più temibile dei luogotenenti di lord Kazzak. Quando la Legione fu sconfitta e Kazzak fu respinto nella Landa Corrotta, il suo padrone affidò a Razelikh il compito di assicurarsi le ⟦Blasted Lands=Terre Devastate⟧.\n\nMentre l'⟦Alliance=Alleanza⟧ combatteva meschine battaglie con l'⟦Horde=Orda⟧ per i territori fuori dalle ⟦Blasted Lands=Terre Devastate⟧, Razelikh riuniva le varie sette del ⟦Shadow Council=Concilio dell'Ombra⟧ e i brutali ogre Maglioinfame della regione.", "." },
  ["51d8635ce3676579"] = { "La scorta di esplosivi va distrutta!", "." },
  ["51dcc9892e219572"] = { "Hai l'aria di <un/una> <uomo/donna> in cerca di conoscenza. Forse cerchi gli insegnamenti della forgia e del martello. Forse posso guidarti su quella strada. Ma solo dopo che avrai accettato gli spiriti e ascoltato il loro richiamo.", "." },
  ["51de421e91ef1104"] = { "Il mio spirito e le mie spoglie sono rimasti a lungo prigionieri qui, a Maraudon, giovane {class}. Il tempo non mi ha dato altro che ampie occasioni per riflettere sui miei errori e capire che la mia gelosia verso Remulos era stolta. Aveva cercato di avvertirmi e di convincermi che il mio legame con Theradras non avrebbe dato nulla di puro, che dal caos sarebbe venuta solo distruzione. Mio fratello aveva ragione.\n\nMa il fatto che tu mi abbia liberato non significa che la mia penitenza sia finita.", "." },
  ["51dec320d372fc54"] = { "L'⟦Alliance=Alleanza⟧ ha preso la fucina!", "." },
  ["51def53cfffaff68"] = { "%s studia il cerchio di pietre, in cerca di segni di cedimento.", "." },
  ["51e0f993f4659a93"] = { "%s comincia a brillare e a fumare!", "." },
  ["51e11d67f8b58bfe"] = { "Non dire a Tirth che sono ancora qui. Se scopre che non ho lasciato le Distese Salate, mi toccherà fargli le commissioni e lavargli i panni sporchi per sempre!", "." },
  ["51e9082eacc418a6"] = { "Vuoi sapere della raccolta delle razioni? Molto bene. Secondo le ultime notizie, l'⟦Horde=Orda⟧ ha preparato $2095w controfiletti di lupo su $2096w. Abbiamo anche messo da parte $2102w pinnagialla maculati al vapore su $2103w e $2105w salmoni impanati sui $2106w necessari.", "." },
  ["51ea6689e6de8cad"] = { "%s bacia la padrona Nagmara", "." },
  ["51eb16ac0ef8abf1"] = { "Se sei qui per farmi perdere tempo, stai facendo perdere tempo all'intero ⟦Cenarion Circle=Circolo Cenariano⟧. Per il tuo bene, speriamo che tu non sia così <sciocco/sciocca> da fare proprio questo.", "." },
  ["51f4a03d141c3ef3"] = { "Mamma!", "." },
})
